 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Repeated full-color separator rows/columns define the tile period.
    row_seps = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    if len(row_seps) >= 2:
        p = row_seps[1] - row_seps[0]
        for r in range(h):
            if r in row_seps:
                continue
            for c in range(w):
                vals = [grid[k][c] for k in range(r % p, h, p) if k not in row_seps and grid[k][c] != bg]
                if vals:
                    out[r][c] = vals[0]
    elif len(col_seps) >= 2:
        p = col_seps[1] - col_seps[0]
        for c in range(w):
            if c in col_seps:
                continue
            for r in range(h):
                vals = [grid[r][k] for k in range(c % p, w, p) if k not in col_seps and grid[r][k] != bg]
                if vals:
                    out[r][c] = vals[0]
    elif row_seps:
        # A single separator marks equal-sized regions on either side.
        sep = row_seps[0]
        p = sep + 1
        for r in range(h):
            if r == sep:
                continue
            src = r % p
            for c in range(w):
                if grid[src][c] != bg:
                    out[r][c] = grid[src][c]
    elif col_seps:
        sep = col_seps[0]
        p = sep + 1
        for c in range(w):
            if c == sep:
                continue
            src = c % p
            for r in range(h):
                if grid[r][src] != bg:
                    out[r][c] = grid[r][src]
    return out
